def bear_fur(bears: list[str]) -> str:
    b1, b2 = bears[0], bears[1]
    if b1 == b2:
        if b1 == 'black':
            return 'black'
        elif b1 == 'brown':
            return 'brown'
        elif b1 == 'white':
            return 'white'

    valid_colors = {'black', 'brown', 'white'}
    if b1 not in valid_colors or b2 not in valid_colors:
        return 'unknown'

    if {b1, b2} == {'black', 'brown'}:
        return 'dark brown'
    if {b1, b2} == {'black', 'white'}:
        return 'grey'
    if {b1, b2} == {'brown', 'white'}:
        return 'light brown'

    return 'unknown'
